def balanced_brackets(string):
    stack = []
    mapping = {')': '(', ']': '[', '}': '{'}
    for ch in string:
        if ch in '({[':
            stack.append(ch)
        elif ch in ')}]':
            if not stack or stack[-1] != mapping[ch]:
                return False
            stack.pop()
    return not stack
